\pset tuples_only on
\pset format unaligned
-- Targets from observed production error and adjacent successful user operation, run 34459720319.
SELECT jsonb_build_object('section','clock','at',clock_timestamp(),'timezone',current_setting('TimeZone'),'connection_ro',current_setting('default_transaction_read_only'),'transaction_ro',current_setting('transaction_read_only'));
SELECT jsonb_build_object('section','target_packing','row',to_jsonb(p)-'payload_hash'-'idempotency_key') FROM pkg_packing_records p WHERE id IN (33,34);
SELECT jsonb_build_object('section','shift','row',to_jsonb(s)) FROM pkg_work_shifts s WHERE id IN (56,57);
SELECT jsonb_build_object('section','grading_reference','packing_id',p.id,'reference',r.code,'grading',to_jsonb(g)-'payload_hash'-'idempotency_key','links',(SELECT COALESCE(jsonb_agg(jsonb_build_object('link',to_jsonb(l),'source',to_jsonb(s))),'[]') FROM pkg_grading_source_links l LEFT JOIN pkg_source_batches s ON s.id=l.source_batch_id WHERE l.grading_id=g.id)) FROM pkg_packing_records p CROSS JOIN LATERAL jsonb_array_elements_text(p.grading_codes_json) r(code) LEFT JOIN pkg_grading_records g ON g.code=r.code WHERE p.id IN (33,34) ORDER BY p.id,g.id;
SELECT jsonb_build_object('section','shift_sources','row',to_jsonb(s)) FROM pkg_source_batches s WHERE shift_id IN (56,57) ORDER BY id;
SELECT jsonb_build_object('section','pkg_audit','row',to_jsonb(a)) FROM pkg_audit_logs a WHERE created_at >= '2026-09-10 09:09:00' AND created_at < '2026-09-10 09:13:00' ORDER BY id LIMIT 30;
SELECT jsonb_build_object('section','operation_log','id',id,'at',created_at,'user_id',user_id,'username',username,'path',request_path,'result',result_status,'biz_id',biz_id,'biz_no',biz_no,'after',after_data) FROM sys_operation_logs WHERE request_path LIKE '%/packaging/terminal/warehouse/confirm%' ORDER BY id DESC LIMIT 10;
SELECT jsonb_build_object('section','sku_combinations','product',v.product,'grade',v.grade,'spec','PKG_PACK_SPEC_3','all_count',count(s.sku_code),'active_count',count(s.sku_code) FILTER (WHERE s.status='ACTIVE'),'rows',COALESCE(jsonb_agg(jsonb_build_object('code',s.sku_code,'name',s.sku_name,'status',s.status)) FILTER (WHERE s.sku_code IS NOT NULL),'[]')) FROM (VALUES ('PRD-EGG-GRADE_5','GRADE_5'),('PRD-EGG-GRADE_1','GRADE_1')) v(product,grade) LEFT JOIN product_skus s ON s.product_code=v.product AND s.grade_code=v.grade AND s.spec_code='PKG_PACK_SPEC_3' GROUP BY v.product,v.grade;
SELECT jsonb_build_object('section','grade_sku_alternatives','row',to_jsonb(s)) FROM product_skus s WHERE grade_code='GRADE_5';
SELECT jsonb_build_object('section','spec','row',to_jsonb(s)) FROM packaging_specs s WHERE spec_code='PKG_PACK_SPEC_3';
SELECT jsonb_build_object('section','grade','row',to_jsonb(g)) FROM product_grades g WHERE grade_code IN ('GRADE_1','GRADE_5');
SELECT jsonb_build_object('section','grade_dict','row',to_jsonb(d)) FROM sys_dict d WHERE dict_type='PKG_EGG_GRADE' AND dict_code IN ('GRADE_1','GRADE_5');
SELECT jsonb_build_object('section','farm','row',to_jsonb(f)) FROM brd_farms f WHERE farm_code IN (SELECT site_id FROM pkg_work_shifts WHERE id IN (56,57));
SELECT jsonb_build_object('section','source_mode','row',to_jsonb(m)) FROM inv_source_mode m WHERE scope_level='GROUP' OR (scope_level='SITE' AND scope_code IN (SELECT site_id FROM pkg_work_shifts WHERE id IN (56,57))) OR (scope_level='COMPANY' AND scope_code IN (SELECT company_code FROM brd_farms WHERE farm_code IN (SELECT site_id FROM pkg_work_shifts WHERE id IN (56,57))));
SELECT jsonb_build_object('section','target_closure','packing_id',p.id,'code',p.code,'handover',(SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(to_jsonb(h)),'[]')) FROM pkg_handover_records h WHERE h.packing_code=p.code),'batches',(SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(to_jsonb(b)),'[]')) FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code OR b.batch_no=p.code),'ledger',(SELECT jsonb_build_object('count',count(*),'rows',COALESCE(jsonb_agg(to_jsonb(l)),'[]')) FROM inv_ledger l WHERE l.ref_no=p.code OR l.batch_no=p.code OR l.batch_no IN (SELECT b.batch_no FROM inv_batches b WHERE b.packaging_batch_ref=p.code OR b.source_no=p.code)),'other_shift_batches',(SELECT COALESCE(jsonb_agg(to_jsonb(b)),'[]') FROM inv_batches b WHERE b.collection_batch_ref='SHIFT-'||p.shift_id::text AND COALESCE(b.packaging_batch_ref,'')<>p.code)) FROM pkg_packing_records p WHERE id IN (33,34);
SELECT jsonb_build_object('section','warehouse_location','location',to_jsonb(l),'warehouse',to_jsonb(w)) FROM wms_locations l LEFT JOIN wms_warehouses w ON w.warehouse_code=l.warehouse_code WHERE l.location_code IN ('CS-KW-MS01') OR l.location_code IN (SELECT location FROM pkg_handover_records WHERE packing_code IN (SELECT code FROM pkg_packing_records WHERE id IN (33,34)));
SELECT jsonb_build_object('section','potential_grade5_scope','id',p.id,'code',p.code,'status',p.status,'is_test',p.is_test,'shift_id',p.shift_id,'outputs',p.batches_json,'handover_count',(SELECT count(*) FROM pkg_handover_records h WHERE h.packing_code=p.code),'batch_count',(SELECT count(*) FROM inv_batches b WHERE b.packaging_batch_ref=p.code),'ledger_count',(SELECT count(*) FROM inv_ledger l WHERE l.ref_no=p.code)) FROM pkg_packing_records p WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(p.batches_json) o WHERE o->>'grade'='GRADE_5' AND o->>'specId'='PKG_PACK_SPEC_3') ORDER BY p.id;
SELECT jsonb_build_object('section','audit_table_columns','table',table_name,'columns',jsonb_agg(column_name ORDER BY ordinal_position)) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('sys_audit_log','sys_operation_logs','wms_inbound') GROUP BY table_name;
